ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_url text, ADD COLUMN IF NOT EXISTS audio_parts jsonb, ADD COLUMN IF NOT EXISTS audio_duration_seconds double precision, ADD COLUMN IF NOT EXISTS meeting_type text DEFAULT 'corporate', ADD COLUMN IF NOT EXISTS processing_error text;
ALTER TABLE public.transcripts ADD COLUMN IF NOT EXISTS start_seconds double precision, ADD COLUMN IF NOT EXISTS end_seconds double precision;
CREATE TABLE public.meeting_audio_segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL, segment_index integer NOT NULL, storage_path text NOT NULL, duration_seconds double precision NOT NULL, offset_seconds double precision NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id, segment_index));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.meeting_audio_segments TO authenticated;
GRANT ALL ON public.meeting_audio_segments TO service_role;
ALTER TABLE public.meeting_audio_segments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read audio segments" ON public.meeting_audio_segments FOR SELECT TO authenticated USING (user_id = auth.uid() AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.user_id=auth.uid()));
CREATE POLICY "Owners insert audio segments" ON public.meeting_audio_segments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.user_id=auth.uid()));
GRANT UPDATE, DELETE ON public.transcripts TO authenticated;
CREATE POLICY "Owners update transcripts" ON public.transcripts FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.user_id=auth.uid()));
CREATE POLICY "Owners delete transcripts" ON public.transcripts FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=meeting_id AND m.user_id=auth.uid()));
CREATE POLICY "Owners upload recordings" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='meeting-recordings' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Owners read recordings" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='meeting-recordings' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Owners delete recordings" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='meeting-recordings' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE TABLE public.meeting_ai_access (id text PRIMARY KEY DEFAULT 'audio', blocked boolean NOT NULL DEFAULT false, status_code integer, message text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.meeting_ai_access TO authenticated;
GRANT ALL ON public.meeting_ai_access TO service_role;
ALTER TABLE public.meeting_ai_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Signed in users read AI availability" ON public.meeting_ai_access FOR SELECT TO authenticated USING(true);
COMMENT ON COLUMN public.meetings.audio_url IS 'Private storage object path, never a public or expiring signed URL.';